#include <string>
#include <vector>

class History
{
public:
    explicit History(std::size_t capacity) : m_capacity{ capacity } {}

    void submit(const std::string& line)
    {
        m_browsing = false;
        m_draft.clear();
        if (line.empty() || (!m_entries.empty() && m_entries.back() == line)) return;
        m_entries.push_back(line);
        if (m_entries.size() > m_capacity) m_entries.erase(m_entries.begin());
    }

    std::string up(const std::string& current)
    {
        if (m_entries.empty()) return current;
        if (!m_browsing)
        {
            m_draft = current;
            m_browsing = true;
            m_at = m_entries.size() - 1;
        }
        else if (m_at > 0)
        {
            --m_at;
        }
        return m_entries[m_at];
    }

    std::string down()
    {
        if (!m_browsing) return m_draft;
        if (m_at + 1 < m_entries.size()) return m_entries[++m_at];
        m_browsing = false;
        return m_draft;
    }

private:
    std::size_t m_capacity;
    std::vector<std::string> m_entries;
    bool m_browsing{ false };
    std::size_t m_at{ 0 };
    std::string m_draft;
};

unitTests:
TEST("the example")
{
    History h{ 10 };
    h.submit("give potion 5"); h.submit("heal");
    CHECK_EQ(h.up("go"), std::string("heal"));
    CHECK_EQ(h.up("ignored"), std::string("give potion 5"));
    CHECK_EQ(h.up("ignored"), std::string("give potion 5"));
    CHECK_EQ(h.down(), std::string("heal"));
    CHECK_EQ(h.down(), std::string("go"));
}
TEST("no history") { History h{ 5 }; CHECK_EQ(h.up("typing"), std::string("typing")); CHECK_EQ(h.down(), std::string("")); }
TEST("empty and repeated lines are not recorded") { History h{ 5 }; h.submit("a"); h.submit(""); h.submit("a"); h.submit("b"); CHECK_EQ(h.up(""), std::string("b")); CHECK_EQ(h.up(""), std::string("a")); CHECK_EQ(h.up(""), std::string("a")); }
TEST("submitting resets browsing") { History h{ 5 }; h.submit("one"); h.submit("two"); h.up(""); h.up(""); h.submit("three"); CHECK_EQ(h.up(""), std::string("three")); }
TEST("capacity drops the oldest") { History h{ 2 }; h.submit("1"); h.submit("2"); h.submit("3"); CHECK_EQ(h.up(""), std::string("3")); CHECK_EQ(h.up(""), std::string("2")); CHECK_EQ(h.up(""), std::string("2")); }
TEST("down past the newest gives the draft once browsing") { History h{ 5 }; h.submit("x"); CHECK_EQ(h.up("draft"), std::string("x")); CHECK_EQ(h.down(), std::string("draft")); CHECK_EQ(h.down(), std::string("draft")); }

